#pragma once

// ============================================================================
//  Canvas Editor branding
//
//  Everything user-facing that names the app lives here, so renaming it or
//  changing the startup greeting is a one-file edit.
//
//  To change the text of the SEKAI-style intro animation, edit INTRO_TEXT
//  below and rebuild. (It can also be overridden at runtime without a rebuild:
//  Settings > Canvas > Intro text.)
// ============================================================================

// Used in window titles, dialogs and "generated by" comments in exported files.
// Must stay a macro: it is concatenated with other string literals.
#define APP_NAME "Canvas Editor"

namespace Canvas::Branding
{
	// Big line shown by the startup animation.
	inline constexpr const char* INTRO_TEXT = "Welcome to Canvas.";

	// Smaller line shown under INTRO_TEXT. Set to "" to hide it.
	inline constexpr const char* INTRO_SUBTEXT = "A chart editor for SEKAI-style rhythm charts";

	// How long the intro stays on screen, in seconds (it can always be skipped
	// with a click or any key).
	inline constexpr float INTRO_DURATION_SECONDS = 3.2f;

	// Folder name used for per-user settings (macOS: ~/Library/Application Support/<name>,
	// Linux: $XDG_CONFIG_HOME/<name>).
	inline constexpr const char* USER_DATA_FOLDER = "CanvasEditor";

	inline constexpr const char* HELP_URL = "https://github.com/Stellarain1/Canvas-Editor#readme";
}
